Следующая реализация на C является примером игры "Змейка", которая использует библиотеку SFML для графического интерфейса:

```c
#include <SFML/Graphics.hpp>

// Константы
const float SNAKE_SPEED = 0.1f;
const float GRID_SIZE = 32.0f;

// Структура для хранения положения змейки
struct SnakePart {
    sf::Vector2f position;
    sf::Texture texture;
};

// Структура для хранения змейки
struct Snake {
    std::vector<SnakePart> parts;
    sf::Vector2f direction;
};

// Структура для хранения яблока
struct Apple {
    sf::Vector2f position;
    sf::Texture texture;
};

// Структура для хранения игрового поля
struct GameField {
    sf::Texture grassTexture;
    sf::Texture wallTexture;
    sf::Texture snakeTexture;
    sf::Texture appleTexture;

    sf::Sprite grass;
    sf::Sprite walls[4];
    Snake snake;
    Apple apple;
};

// Функции для обновления и отрисовки игры
void updateSnake(GameField* gameField, float deltaTime);
void drawSnake(sf::RenderTarget& target, const GameField& gameField);

void updateApple(GameField* gameField, float deltaTime);
void drawApple(sf::RenderTarget& target, const GameField& gameField);

void updateWalls(sf::RenderTarget& target, const GameField& gameField);
void drawWalls(sf::RenderTarget& target, const GameField& gameField);

void updateGameField(GameField* gameField, float deltaTime);
void drawGameField(sf::RenderTarget& target, const GameField& gameField);

// Основная функция игры
int main() {
    sf::ContextSettings settings;
    settings.antialiasingLevel = sf::ContextSettings::AntialiasingLevel::Level_4;

    sf::RenderWindow window(sf::VideoMode(640, 640), "Snake", sf::Style::Default, settings);

    // Инициализация игрового поля
    GameField gameField;
    gameField.grassTexture.loadFromFile("grass.png");
    gameField.wallTexture.loadFromFile("wall.png");
    gameField.snakeTexture.loadFromFile("snake.png");
    gameField.appleTexture.loadFromFile("apple.png");

    gameField.grass.setTexture(gameField.grassTexture);
    gameField.walls[0].setTexture(gameField.wallTexture);
    gameField.walls[1].setTexture(gameField.wallTexture);
    gameField.walls[2].setTexture(gameField.wallTexture);
    gameField.walls[3].setTexture(gameField.wallTexture);

    gameField.snake.parts.emplace_back();
    gameField.snake.parts[0].position = sf::Vector2f(10 * GRID_SIZE, 10 * GRID_SIZE);
    gameField.snake.parts[0].texture = gameField.snakeTexture;
    gameField.snake.direction = sf::Vector2f(GRID_SIZE, 0.0f);

    gameField.apple.position = sf::Vector2f(20 * GRID_SIZE, 20 * GRID_SIZE);
    gameField.apple.texture = gameField.appleTexture;

    // Цикл игры
    while (window.isOpen()) {
        sf::Event event;
        while (window.pollEvent(event)) {
            if (event.type == sf::Event::Closed) {
                window.close();
            }
            else if (event.type == sf::Event::KeyPressed) {
                switch (event.key.code) {
                case sf::Keyboard::Up:
                    if (gameField.snake.direction.y != GRID_SIZE)
                        gameField.snake.direction = sf::Vector2f(0.0f, -GRID_SIZE);
                    break;
                case sf::Keyboard::Down:
                    if (gameField.snake.direction.y != -GRID_SIZE)
                        gameField.snake.direction = sf::Vector2f(0.0f, GRID_SIZE);
                    break;
                case sf::Keyboard::Left:
                    if (gameField.snake.direction.x != GRID_SIZE)
                        gameField.snake.direction = sf::Vector2f(-GRID_SIZE, 0.0f);
                    break;
                case sf::Keyboard::Right:
                    if (gameField.snake.direction.x != -GRID_SIZE)
                        gameField.snake.direction = sf::Vector2f(GRID_SIZE, 0.0f);
                    break;
                }
            }
        }

        float deltaTime = window.restart().getDeltaTime();

        updateGameField(&gameField, deltaTime);

        window.clear(sf::Color::White);
        drawGameField(window, gameField);
        window.display();
    }

    return 0;
}

// Функции для обновления и отрисовки игры
void updateSnake(GameField* gameField, float deltaTime) {
    for (size_t I = gameField->snake.parts.size() - 1; I > 0; --i) {
        gameField->snake.parts[i].position = gameField->snake.parts[i - 1].position;
    }

    sf::Vector2f newPosition = gameField->snake.parts[0].position + gameField->snake.direction;
    gameField->snake.parts[0].position = newPosition;

    if (gameField->snake.parts[0].position == gameField->apple.position) {
        gameField->snake.parts.emplace_back();
        gameField->apple.position = sf::Vector2f(
            static_cast<int>(sf::Random::float_(0, 20)) * GRID_SIZE,
            static_cast<int>(sf::Random::float_(0, 20)) * GRID_SIZE);
    }
}

void drawSnake(sf::RenderTarget& target, const GameField& gameField) {
    for (const auto& part : gameField.snake.parts) {
        target.draw(part.texture, sf::IntRect(0, 0, 32, 32), part.position);
    }
}

void updateApple(GameField* gameField, float deltaTime) {
    if (gameField->apple.position == gameField->snake.parts[0].position) {
        gameField->apple.position = sf::Vector2f(
            static_cast<int>(sf::Random::float_(0, 20)) * GRID_SIZE,
            static_cast<int>(sf::Random::float_(0, 20)) * GRID_SIZE);
    }
}

void drawApple(sf::RenderTarget& target, const GameField& gameField) {
    target.draw(gameField.apple.texture, sf::IntRect(0, 0, 32, 32), gameField.apple.position);
}

void updateWalls(sf::RenderTarget& target, const GameField& gameField) {
    for (sf::Sprite& wall : gameField.walls) {
        wall.setPosition(sf::Vector2f(wall.getPosition().x, wall.getPosition().y + GRID_SIZE));
        if (wall.getPosition().y > 640 - GRID_SIZE) {
            wall.setPosition(sf::Vector2f(wall.getPosition().x, 0));
        }
        target.draw(wall);
    }
}

void drawWalls(sf::RenderTarget& target, const GameField& gameField) {
    for (const sf::Sprite& wall : gameField.walls) {
        target.draw(wall);
    }
}

void updateGameField(GameField* gameField, float deltaTime) {
    updateSnake(gameField, deltaTime);
    updateApple(gameField, deltaTime);
    updateWalls(window, *gameField);
}

void drawGameField(sf::RenderTarget& target, const GameField& gameField) {
    target.draw(gameField.grass);

    drawWalls(target, gameField);
    drawSnake(target, gameField);
    drawApple(target, gameField);
}
```

